parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "sheetId": {
      "type": "string",
      "description": "The user's Google Sheet ID"
    },
    "action": {
      "type": "string",
      "enum": ["update", "delete"],
      "description": "Whether to update or delete the transaction"
    },
    "target": {
      "type": "object",
      "properties": {
        "findLast": { "type": "boolean", "description": "Set true if user refers to their last or previous transaction" },
        "oldAmount": { "type": "number", "description": "The previous amount to find (if mentioned)" },
        "vendorOrItem": { "type": "string", "description": "The merchant, vendor, or item name (e.g. sunscreen, Swiggy, mom)" }
      },
      "description": "Details to pinpoint the exact transaction"
    },
    "newValues": {
      "type": "object",
      "properties": {
        "amount": { "type": "number", "description": "The new corrected amount" },
        "vendor": { "type": "string", "description": "The new corrected vendor or merchant" },
        "category": { "type": "string", "description": "The new category" }
      },
      "description": "The new corrected values to apply when action is update"
    }
  },
  "required": ["sheetId", "action"]
}
